    {
      "heading": "Parameters",
      "blocks": [
        {
          "kind": "h3",
          "text": "Metrics"
        },
        {
          "kind": "table",
          "table": {
            "headers": [
              "Parameter",
              "Default",
              "Meaning"
            ],
            "rows": [
              [
                "Phase source",
